            if a > 0:
                break
            if i > 0 and a == nums[i - 1]:
                continue
            l, r = (i + 1, len(nums) - 1)
            while l < r:
                threeSum = a + nums[l] + nums[r]
                if threeSum > 0:
                    r -= 1
                elif threeSum < 0:
                    l += 1
                else:
